import os,glob,re,json
from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def f(g):
    H,W=len(g),len(g[0])
    def nb(i,j):
        c=0
        for di in(-1,0,1):
            for dj in(-1,0,1):
                if (di,dj)!=(0,0) and 0<=i+di<H and 0<=j+dj<W and not g[i+di][j+dj]==g[i][j]: c+=1
        return c
    out=[row[:] for row in g]
    for i in range(H):
        for j in range(W):
            if nb(i,j)>2: continue
            if nb(i,j)<2:
                best,v=0,-1
                for di in(-1,0,1):
                    for dj in(-1,0,1):
                        if (di,dj)!=(0,0) and 0<=i+di<H and 0<=j+dj<W:
                            best=max(best,v=Counter([g[i+di][j+dj]])[max(Counter([g[i+di][j+dj]])[g[i+di][j+dj]]),v]))
                if v>=best: pass
            # simpler: replace with most common non-self neighbor
            cnt=Counter()
            for di in(-1,0,1):
                for dj in(-1,0,1):
                    if (di,dj)!=(0,0) and 0<=i+di<H and 0<=j+dj<W: cnt[g[i+di][j+dj]]+=1
            mx,mxk=0,None
            for k,cntv in cnt.items():
                if cntv>mx: mx,k=cntv,k
            out[i][j]=k if cnt[g[i][j]]==1 else out[i][j]
    return out

# demo1: remove single stray cells -> fill with dominant neighbor color
print(json.dumps(f(G['Demo pair 1 input']))==json.dumps(G['Demo pair 1 output']))
T=G['Test input']
for row in T: print(' '.join(map(str,row)))
o=f(T); print(json.dumps(o))

