import os,re,json
from collections import Counter,deque
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def f(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]
    out=[row[:] for row in g]
    def nb(i,j):
        for di in(-1,0,1):
            for dj in(-1,0,1):
                if 0<=i+di<H and 0<=j+dj<W: yield g[i+di][j+dj]
    for i in range(H):
        for j in range(W):
            if not seen[i][j]:
                col=g[i][j]; q=deque([(i,j)]); comp=[]; seen[i][j]=True
                while q:
                    a,b=q.popleft(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]==col:
                            seen[x][y]=True; q.append((x,y))
                rs=[p for p,_ in comp]; cs=[q for _,q in comp]
                # is component a full rectangle of size>=2?
                h=max(rs)-min(rs)+1; w=max(cs)-min(cs)+1
                ok = len(comp)>=2 and len(comp)==h*w
                if not ok:
                    cnt=Counter(nb(*comp[0]))
                    mx,cntv=cnt.most_common(1)[0]
                    for a,b in comp: out[a][b]=mx
    return out

print(json.dumps(f(G['Demo pair 1 input']))==json.dumps(G['Demo pair 1 output']))
T=G['Test input']
for r in T: print(' '.join(map(str,r)))
o=f(T)
print(json.dumps(o))

inp=G['Demo pair 1 input']; out=G['Demo pair 1 output']
