def f(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[r[:] for r in g]
    comps=[]
    for i in range(H):
        for j in range(W):
            if not seen[i][j]:
                col=g[i][j]; q=deque([(i,j)]); comp=[]; seen[i][j]=True
                while q:
                    a,b=q.popleft(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]==col:
                            seen[x][y]=True; q.append((x,y))
                rs=[p for p,_ in comp]; cs=[q for _,q in comp]
                h=max(rs)-min(rs)+1; w=max(cs)-min(cs)+1
                if len(comp)>=2 and len(comp)==h*w: comps.append((col,comp,min(rs),max(rs),min(cs),max(cs)))
    for col,comp,r0,r1,c0,c1 in comps:
        bgh=set()
        for a,b in comp:
            for di in(-1,0,1):
                for dj in(-1,0,1):
                    x,y=a+di,b+dj
                    if 0<=x<H and 0<=y<W and (x,y) not in comp: bgh.add(g[x][y])
        # fill noise inside bbox with bg majority
        cnt=Counter(bgh)
        for a in range(r0,r1+1):
            for b in range(c0,c1+1):
                if g[a][b]!=col: out[a][b]=cnt.most_common(1)[0][0]
    return out
