    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; res=[]
    for i in range(H):
        for j in range(W):
            if not seen[i][j]:
                col=g[i][j]; q=deque([(i,j)]); comp=[]; seen[i][j]=True
                while q:
                    a,b=q.popleft(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]==col:
                            seen[x][y]=True; q.append((x,y))
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                hgt=max(rs)-min(rs)+1; wdg=max(cs)-min(cs)+1
                isrect = len(comp)==hgt*wdg
                res.append({'col':col,'isrect':isrect,'n':len(comp),'comp':comp})
    return res
def f(g):
    H,W=len(g),len(g[0])
    cc=comps(g)
    out=[r[:] for r in g]
    # pick the biggest component as background-region anchor? In test bg=9 is scattered rects though.
    # New idea: singleton takes color of nearest *other* non-singleton component; tie/none -> keep? or bg?
    for c in cc:
        if len(c['comp'])==1:
            i,j=c['comp'][0]
            best=None
            for cand in cc:
                if cand is c or len(cand['comp'])==1: continue
                cells=cand['comp']
                dist=min(abs(a-i)+abs(b-j) for a,b in cells)
                if best is None or dist<best[0]: best=(dist,cand['col'],cells)
            if best is not None:
                out[i][j]=best[1]
    return out
print('demo ok:', json.dumps(f(G['Demo pair 1 input']))==json.dumps(G['Demo pair 1 output']))
o=f(G['Test input'])
for i in range(19):
    for j in range(12):
        if G['Test input'][i][j]!=o[i][j]: print(i,j,G['Test input'][i][j],'->',o[i][j])
print(json.dumps(o))

